import{_ as i,l as r,o as e,c as n,v as t,p as s,x as l,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"校准集","description":"","frontmatter":{"title":"校准集","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/calibration-set.md","filePath":"llm/calibration-set.md","lastUpdated":1789023840000}'),m={name:"llm/calibration-set.md"};function E(c,a,_,u,A,P){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="校准集" tabindex="-1">校准集 <a class="header-anchor" href="#校准集" aria-label="Permalink to &quot;校准集&quot;">​</a></h1><div class="epigraph"><p>PTQ 不回传，只问校准样本：动态范围、Hessian、哪一通道重要，都从这一小撮激活里读。集偏了，格子就对准错误的世界。</p><footer>—— 对照 GPTQ / AWQ / SmoothQuant 用数百段文本缓存激活的做法</footer></div><p><a href="/llm/quant-granularity">粒度</a> 决定 \\(s\\) 管多宽。本课写 \\(s\\) 从哪来： <strong>校准集</strong>。缺口不是再讲 round，而是样本如何代表部署分布——以及为何「C4 上 PPL 好看」换指令数据就炸。<a href="/llm/gptq">GPTQ</a> 已强调过拟合校准域；本课把集的构造做成一课，供 AdaRound、Hessian、混精搜索共用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>校准要覆盖：语言域、长度、特殊 token、多模态前缀（若有）、以及会激发<a href="/llm/why-activation-outliers">离群通道</a> 的那些模式。条数通常几十到几百：太少，max/百分位与 \\(XX^\\top\\) 不稳；太多，PTQ 失去「数小时打完」的意义，并开始像微型训练。</p><p>域偏移：用网页文本校准聊天模型，指令格式与代码块上的激活统计会变，\\(s\\) 偏小则饱和，偏大则台阶变粗。长上下文：短校准看不见 RoPE 相关爆炸，线上长请求才饱和。问题是 <strong>校准分布 = 部署分布的代理</strong>，不是「随便抓 128 条」。</p><p><span class="marginnote">QAT 用训练数据过量化噪声，不叫本课的校准集。本课只限 PTQ：冻结权重，用前向激活估统计量或解重建。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造：从目标域分层抽样（通用、代码、多语、超长各留配额），固定种子以便复现。预处理与推理一致：同样的 chat template、同样的系统提示、同样的最大长度。缓存每层输入 \\(X\\) 时，用将要部署的精度路径（已经量化的前层）——<a href="/llm/gptq">GPTQ</a> 写过误差要沿真实路径走。</p><p>统计：min/max 或百分位估 \\(s,z\\)；百分位抗单个异常 token，但可能系统性地低估真离群。可报两条：\\(p=100\\) 与 \\(p=99.9\\)，看下游谁稳。Hessian / 重建类方法对 \\(X\\) 的二阶更敏感，校准条数不够时要阻尼，方法退化。</p>',10)),(e(),s(h,null,{default:l(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E7%9B%AE%E6%A0%87%E9%83%A8%E7%BD%B2%E5%9F%9F%22%5D%20--%3E%20SMP%5B%22%E5%88%86%E5%B1%82%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20SMP%20--%3E%20FWD%5B%22%E6%8C%89%E7%9C%9F%E5%AE%9E%E8%B7%AF%E5%BE%84%E5%89%8D%E5%90%91%22%5D%0A%20%20FWD%20--%3E%20X%5B%22%E7%BC%93%E5%AD%98%E5%B1%82%E8%BE%93%E5%85%A5%22%5D%0A%20%20X%20--%3E%20S%5B%22%E4%BC%B0%E8%AE%A1%20s%2C%20z%20%E6%88%96%20Hessian%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要用评测集当校准集：既污染评测，又往往太「干净」，估不出脏输入上的饱和。校准与评测要拆开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(max|X|\\) 由极值 token 决定，方差巨大，所以纯 min/max 不稳定。百分位把极值当离群扔掉，若极值其实是功能通道，等于系统性欠载。消融应用<a href="/llm/why-activation-outliers">离群课</a> 的钳制实验：扔掉的百分位若伤 CE，就不要用那么低的 \\(p\\)。</p><p>层间：前层量化改变后层 \\(X\\)。一次性用 FP16 激活给所有层估 \\(s\\)，会乐观。逐层用已量化前缀，校准时间涨，偏差降。这是准确性机制，不是实现癖好。</p><p><span class="marginnote">MoE：校准必须让各专家都被打到，否则冷专家的 \\(s\\) 来自噪声。路由若随域变，专家尺度在线上会错。共享专家优先保证覆盖。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把论文附录的 pile 子集当你的产品校准。不要在换 tokenizer 或 chat 模板后复用旧 \\(s\\)。不要把校准做成每天全量——固定一版，变更要走发布。下一课 AdaRound 在给定校准 \\(X\\) 上改舍入，校准偏了它会更用力地拟合错误世界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PTQ 的格子与重建全部读校准激活；集必须代理部署域与长度。</li><li>条数在「统计稳定」与「仍是 PTQ」之间；用真实量化路径缓存 \\(X\\)。</li><li>百分位抗噪但可能切掉功能离群；要消融。</li><li>校准与评测分离；模板变更即作废。</li><li>出处：GPTQ/AWQ/SmoothQuant 的校准实践。</li></ul>',9))])}const B=i(m,[["render",E]]);export{f as __pageData,B as default};
